QState LocaSvr_MessageProcess(LocaSvr * const me, QEvt const * const e) {
    QState status_;
	Cat1Svr *cat1 = &AO_Cat1Svr;
	
    switch (e->sig) {
        
        case Q_ENTRY_SIG: {
            QTimeEvt_armX(&me->timeEvt, 3U * BSP_TICKS_PER_SEC, 0U);
            //包装成json数据并通过MQTT发送出去
            printf("Loca Enter MessageProcess state");

            if (me->jsonBuf != NULL) {
                char sendSting[2048] = {0};
                char* at_prefix = "MQTT_SEND=";
                char* sub_topic = NULL;//"/iotplat/datapush3/sos/WARNCARD3/862288087542898";
                char* json_data = me->jsonBuf;

				sub_topic =  get_topic(me->locate_type,cat1->IMEI);
				

                sprintf(sendSting, "%s%s,%s\r\n", at_prefix, sub_topic, json_data);

                printf("sendSting:[%s]\n",sendSting);
                //cli_execute_string(sendSting);
                app_uart_transmit_sync(APP_UART_ID_4, (uint8_t *)sendSting, strlen(sendSting), 1000);

				if (sub_topic != NULL) {
					free(sub_topic);
					sub_topic = NULL;
				}	
            }


            status_ = Q_HANDLED();
            break;
        }
        
        case Q_EXIT_SIG: {
            if (me->jsonBuf != NULL) {
                free(me->jsonBuf);
                me->jsonBuf = NULL;
                printf("JSON buffer free OK\n");
            }
            (void)QTimeEvt_disarm(&me->timeEvt);
            printf("Loca Exit MessageProcess  state");


            status_ = Q_HANDLED();
            break;
        }
        
        case MQTT_SEND_OK_SIG: {
            status_ = Q_TRAN(&LocaSvr_Idle);
            break;
        }
        
        case TIMEOUT_SIG: {
            status_ = Q_TRAN(&LocaSvr_Idle);
            break;
        }
        default: {
            status_ = Q_SUPER(&LocaSvr_SosControl);
            break;
        }
    }
    return status_;
}


QState LocaSvr_BeaconProcess(LocaSvr * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        
        case Q_ENTRY_SIG: {
            //SOS按键按下3s(可配置)
            me->BEACONData.count = 0U;
            me->BEACONData.timestamp = 0U;
            // 可选：清空整个列表，防止旧指针残留
            memset(me->BEACONData.list, 0, sizeof(me->BEACONData.list));
            /* SAM | 2026-11-07 12:17 +08:00 | Keep periodic cleanup from stopping SOS/find-device beacon collection. */
            yp_scan_sched_radio_hold(YP_SCAN_HOLD_LOCATION, true);
			ble_scanner_start();
            //===========================================
            QTimeEvt_armX(&me->timeEvt, 3U * BSP_TICKS_PER_SEC, 0U);
            printf("Loca Enter BeaconProcess state");

            status_ = Q_HANDLED();
            break;
        }
        
        case Q_EXIT_SIG: {

            /* SAM | 2026-11-07 12:17 +08:00 | Release the radio lease on every state exit, including cancellation. */
            yp_scan_sched_radio_hold(YP_SCAN_HOLD_LOCATION, false);
            printf("Loca Exit BeaconProcess\n");

            (void)QTimeEvt_disarm(&me->timeEvt);
            status_ = Q_HANDLED();
            break;
        }
        
        case BEACON_DATA_SIG: {
            BeaconDataEvt const *evt = (BeaconDataEvt const *)e;
            BeaconScanResult *pBuf = &me->BEACONData;
            int macIdx = -1;
            /* SAM | 2026-10-04 11:07 +08:00 | Fix full-cache selection:
             * start above valid RSSI values so the weakest entry is found.
             * Keep this fix when regenerating cat1svr.c from fsm.qm. */
            int8_t minRssi = 127;
            uint8_t minPos = 0;

			printf("BEACON_DATA_SIG count = %d\n",pBuf->count);

            //① 查找MAC是否已存在缓存
            for(uint8_t i=0; i < pBuf->count; i++)
            {
                if(memcmp(pBuf->list[i].addr, evt->addr, 6U) == 0)
                {
                    macIdx = i;
                    break;
                }
            }

            if(macIdx >=0)
            {
                // 同MAC：更新为最新数据（RSSI、major/minor）
                pBuf->list[macIdx].rssi = evt->rssi;
                pBuf->list[macIdx].major = evt->data.major;
                pBuf->list[macIdx].minor = evt->data.minor;
            }
            else
            {
                // 新MAC
                if(pBuf->count < MAX_BEACON_PER_SCAN)
                {
                    // 未满5个，直接追加
                    pBuf->list[pBuf->count].rssi = evt->rssi;
                    memcpy(pBuf->list[pBuf->count].addr, evt->addr,6);
                    pBuf->list[pBuf->count].major = evt->data.major;
                    pBuf->list[pBuf->count].minor = evt->data.minor;
                    pBuf->count++;
                }
                else
                {
                    // 已满5，找列表里RSSI最弱项
                    for(uint8_t i=0; i<MAX_BEACON_PER_SCAN; i++)
                    {
                        if(pBuf->list[i].rssi < minRssi)
                        {
                            minRssi = pBuf->list[i].rssi;
                            minPos = i;
                        }
                    }
                    // 新信号更强则替换
                    if(evt->rssi > minRssi)
                    {
                        pBuf->list[minPos].rssi = evt->rssi;
                        memcpy(pBuf->list[minPos].addr, evt->addr,6);
                        pBuf->list[minPos].major = evt->data.major;
                        pBuf->list[minPos].minor = evt->data.minor;
                    }
                    // 新信号更弱：直接丢弃
                }
            }
            status_ = Q_HANDLED();
            break;
        }
        
        case TIMEOUT_SIG: {
            // 1.给当前这一帧填充序号、时间戳

            me->BEACONData.timestamp = get_current_unix_timestamp();

            // 2.打印本周期有效beacon数量
            printf("Beacon timeout | ValidBeaconCnt = %d\n", me->BEACONData.count);

            if (me->BEACONData.count > 0) {

                  if (me->BEACONData.count > 0) {
                        BeaconScanResult *pScan = &me->BEACONData;
                        cJSON *root = cJSON_CreateObject();
				  
						cJSON_AddStringToObject(root, "MsgType", get_msg_type(me->locate_type));
						if(me->locate_type == LOCATE_TYPE_SOS)
						{
	                        cJSON_AddNumberToObject(root, "RelatedValue", get_current_unix_timestamp() + 300);
	                        

						}
						else if(me->locate_type == LOCATE_TYPE_FIND_DEVICE)
						{
							cJSON_AddNumberToObject(root, "ReceiveCmdTime", s_receive_find_time);
						}
						else 
						{
							cJSON_AddStringToObject(root, "Version", "V01");
							cJSON_AddNumberToObject(root, "Battery", 80);

						}
						cJSON_AddNumberToObject(root, "Time", pScan->timestamp);
                        cJSON *posObj = cJSON_CreateObject();
                        cJSON_AddStringToObject(posObj, "PositionType", "Bluetooth");
                        cJSON *beaconArr = cJSON_CreateArray();

                        for (uint8_t i = 0; i < pScan->count; i++) {
                            BeaconItem *item = &pScan->list[i];
                            cJSON *beaconItem = cJSON_CreateObject();
                            cJSON_AddNumberToObject(beaconItem, "Major", item->major);
                            cJSON_AddNumberToObject(beaconItem, "Minor", item->minor);
                            cJSON_AddNumberToObject(beaconItem, "Rssi", item->rssi);
                            cJSON_AddItemToArray(beaconArr, beaconItem);
                        }

                        cJSON_AddItemToObject(posObj, "Beacon", beaconArr);
                        cJSON_AddItemToObject(root, "Position", posObj);

                        char *tmpJson = cJSON_PrintUnformatted(root);
                        if (tmpJson != NULL) {
                            if (me->jsonBuf != NULL) {
                                free(me->jsonBuf);
                                me->jsonBuf = NULL;
                            }

                            uint16_t len = strlen(tmpJson) + 1;
                            me->jsonBuf = (char *)malloc(len);
                            if (me->jsonBuf != NULL) {
                                memcpy(me->jsonBuf, tmpJson, len);
                            }
                            cJSON_free(tmpJson);
                        }

                        // 释放 JSON 树
                        cJSON_Delete(root);
                   }
                status_ = Q_TRAN(&LocaSvr_MessageProcess);
            }
            
            else if (me->BEACONData.count == 0) {
                //printf("BeaconNum==0");
                status_ = Q_TRAN(&LocaSvr_WIFI);
            }
            else {
                status_ = Q_UNHANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&LocaSvr_SosControl);
            break;
        }
    }
    return status_;
}


QState LocaSvr_LBS(LocaSvr * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        
        case Q_ENTRY_SIG: {
            QTimeEvt_armX(&me->timeEvt, 15U * BSP_TICKS_PER_SEC, 0U);
            //初始化 LBS_TIMMER
            printf("Loca Enter LBS state");
			Cat_start_lbs_scan();
            status_ = Q_HANDLED();
            break;
        }
        
        case Q_EXIT_SIG: {
            printf("Loca Exit LBS state");
            (void)QTimeEvt_disarm(&me->timeEvt);
            status_ = Q_HANDLED();
            break;
        }
        
        case TIMEOUT_SIG: // intentionally fall through
        case LBS_PROCESS_DONE_SIG: {
            //printf("LBS timeout\n");
            
            if (me->LBSData==0) {
                //printf("me->LbsData==0");
                status_ = Q_TRAN(&LocaSvr_GPS);
            }
            
            else if (me->LBSData != 0) {
				cJSON *root = cJSON_CreateObject();
				cJSON *wifi_result;
				
				cJSON_AddStringToObject(root, "MsgType", get_msg_type(me->locate_type));
				if(me->locate_type == LOCATE_TYPE_SOS)
				{
					cJSON_AddNumberToObject(root, "RelatedValue", get_current_unix_timestamp() + 300);
					
				
				}
				else if(me->locate_type == LOCATE_TYPE_FIND_DEVICE)
				{
					cJSON_AddNumberToObject(root, "ReceiveCmdTime", s_receive_find_time);
				}
				else 
				{
					cJSON_AddStringToObject(root, "Version", "V01");
					cJSON_AddNumberToObject(root, "Battery", 80);
				
				}

				cJSON_AddNumberToObject(root, "Time", get_current_unix_timestamp());
				
				wifi_result = cJSON_Parse(me->scan_result);
				cJSON_AddItemToObject(root, "Position", wifi_result);

				char *tmpJson = cJSON_PrintUnformatted(root);

	            if (tmpJson != NULL) {

					if (me->jsonBuf != NULL) {
						free(me->jsonBuf);
						me->jsonBuf = NULL;
					}
					if (me->scan_result != NULL) {
						free(me->scan_result);
						me->scan_result = NULL;
					}

					uint16_t len = strlen(tmpJson) + 1;
					me->jsonBuf = (char *)malloc(len);
					if (me->jsonBuf != NULL) {
						memcpy(me->jsonBuf, tmpJson, len);
					}
					cJSON_free(tmpJson);
					cJSON_Delete(root);

					status_ = Q_TRAN(&LocaSvr_MessageProcess);
				}

            }
            else {
                status_ = Q_UNHANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&LocaSvr_SosControl);
            break;
        }
    }
    return status_;
}

